CREATE OR REPLACE FUNCTION private.screen_order_reach(p_order_id uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ select private.screen_order_reach(p_order_id, 1) $function$;

